insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('nijigasaki-loft-2026','nijigasaki-loft-2026','『ラブライブ！虹ヶ咲学園スクールアイドル同好会』POP UP STORE がロフト2 店舗で開催決定！','虹咲学园 × Loft 幼稚园老师主题快闪','快闪店','东京、大阪两店先行销售幼稚园老师主题新绘商品，附会场限定满赠。大阪场按休店日前后分段，避免旅行匹配到休店日。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/15/1002/Hhk7MTBaF0EYEinT/ayqcTunH03zNIgTw.jpeg","alt":"虹咲学园 × Loft 幼稚园老师主题快闪 · 官方公告图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6703","checked_on":"2026-10-28"}',null,'["大阪 12/31、1/1 休业。","吉祥寺 10:30–20:00；难波 11:00–21:00，各场最后一天 17:00 结束。","拥挤时可能限流或发整理券。普通商品每款每次结账限 3 件；随机商品限 3 盒或同等散件数量。","通販不附本次会场满赠。实时商品和赠品库存未知。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[{"id":"niji-loft-sticker","title":"每满 ¥3,000：随机迷你贴纸（13 款）","rule":"同次结账每满 3,000 日元含税送 1 张；不可合并小票，不能选款，通販不附赠。","threshold_yen":3000,"threshold_quantity":null,"channel":"门店","scope":"仅各 Loft 会场营业期间的活动商品","venue_ids":[],"starts_on":"2026-11-18","ends_on":"2027-01-05","selection":"随机","receipt_combination":"不可合并","while_supplies_last":true,"image":{"url":"https://www.cocollabo.net/cdn/shop/files/LLniji_26_1_nobelty.jpg?v=14687192447261585651","alt":"Loft 会场限定迷你贴纸（13 款）","source_url":"https://www.cocollabo.net/pages/nijigasaki","checked_on":"2026-10-28"},"source_url":"https://www.cocollabo.net/pages/nijigasaki","checked_on":"2026-10-28"}]','[{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/15/1002/Cv4N4nrNGHWA158P/dJtkaYHzSUC8goOh.jpeg","alt":"Loft 先行销售商品一览","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6703","checked_on":"2026-10-28"}]') on conflict do nothing;
