insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('lovelive-hep-navio-2026','lovelive-hep-navio-2026','「THEキャラCAFE HEPナビオ店×ラブライブ！シリーズ」開催決定！','LoveLive! 系列 × THEキャラCAFE HEP NAVIO','联动咖啡厅','LoveLive! 系列联动餐饮与新商品预告。已核实举办日期与首四天预约；商品明细、价格及特典条件尚待后续公告。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/09/1002/GK3AgAlpsasz7DKM/fmNiUKzayY4InVz5.jpeg","alt":"LoveLive! 系列 × THEキャラCAFE HEP NAVIO · 官方公告图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6692","checked_on":"2026-10-28"}',null,'["这是系列共同联动；不能将未公布菜单都标作虹咲专属。","采用官网更正后的 10/27 20:00 开放时间，旧版 10/19 时间无效。","本公告未公布满赠门槛，不推定有消费特典。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[]','[]') on conflict do nothing;
