insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('nijigasaki-volks-2026','nijigasaki-volks-2026','ラブライブ！虹ヶ咲学園スクールアイドル同好会 POP UP STORE in ボークス','虹咲学园「花之女神」Volks 快闪（已结束）','快闪店','花之女神主题新绘商品快闪，两个会场均已结束，仅供历史查询。','{"url":"https://www.team-e.co.jp/popup/lovelive/images/index.jpg","alt":"虹咲学园「花之女神」Volks 快闪（已结束） · 官方公告图","source_url":"https://www.team-e.co.jp/popup/lovelive/","checked_on":"2026-10-28"}',null,'["活动已结束，不作为近期可参加活动展示。","拥挤时可能限制入场或商品购买数量。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[{"id":"niji-volks-postcard","title":"每满 ¥3,000：随机明信片（13 款）","rule":"会场内指定商品每满 3,000 日元含税送 1 张，随机发放、不可选款、不可合并小票；赠完即止。","threshold_yen":3000,"threshold_quantity":null,"channel":"门店","scope":"活动会场内的指定商品","venue_ids":[],"starts_on":"2026-09-18","ends_on":"2026-10-25","selection":"随机","receipt_combination":"不可合并","while_supplies_last":true,"image":{"url":"https://www.team-e.co.jp/popup/lovelive/images/goods/tokuten.jpg","alt":"花之女神满赠明信片","source_url":"https://www.team-e.co.jp/popup/lovelive/","checked_on":"2026-10-28"},"source_url":"https://www.team-e.co.jp/popup/lovelive/","checked_on":"2026-10-28"}]','[{"url":"https://www.team-e.co.jp/popup/lovelive/images/goods/itemlist.jpg","alt":"花之女神商品与含税价格一览","source_url":"https://www.team-e.co.jp/popup/lovelive/","checked_on":"2026-10-28"}]') on conflict do nothing;
