insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-aab9c2d03dc15575','official-aab9c2d03dc15575','Ave Mujica 8th LIVE「Discrimen Fati」','Ave Mujica 第8次演唱会「Discrimen Fati」','音乐和声优活动','2027年5月29日、30日在 Kアリーナ横浜 举办。最速先行于2026年10月25日20:00至12月6日23:59受理，使用迷你专辑「神の名を」首批附券。单日指定席与两日通票分别受理，抽选优先顺序有特别规定。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/23171008/fb5e4f97-d6cee7d9-06a58ce7-aa638717.png","alt":"Ave Mujica 第8次演唱会「Discrimen Fati」","source_url":"https://bang-dream.com/events/avemujica-8th/","checked_on":"2026-10-29"}','[]','[]','[{"title":"申请资格","text_zh":"需要迷你专辑「神の名を」首批生产版附带的申请券。","evidence_ja":"※ Ave Mujica ミニAlbum「神の名を」 初回生産分に封入の申込券でご応募いただけます。","id":"auto-aab9c2d03dc15575-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/avemujica-8th/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"两日通票","text_zh":"两日通票对应一般指定席，含税12,100日元；中签后两天座位不同。","evidence_ja":"※通しチケットで当選された場合、座席は2日間で異なります。","id":"auto-aab9c2d03dc15575-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/avemujica-8th/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"抽选顺序","text_zh":"同时申请单日票与通票时：附周边S/A席单日票优先，其次一般指定席两日通票，最后一般指定席单日票。","evidence_ja":"単日券【S席(特製グッズ付き)】【A席(特製グッズ付き)】＞2DAYS通しチケット【一般指定席】＞単日券【一般指定席】","id":"auto-aab9c2d03dc15575-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/avemujica-8th/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"序列码与申请次数","text_zh":"每个序列码可对S/A附周边票、一般指定单日票、一般指定两日通票三类受理，分别对各公演申请一次。同日不会在多种席位重复中签；系统允许同场提交两次也只按一次计。S/A单日票可填至第二志愿，其他两类仅第一志愿。","evidence_ja":"※シリアル1枚につき、\n・【S席(特製グッズ付き)】【A席(特製グッズ付き)】\n・【一般指定席】\n・2DAYS通しチケット【一般指定席】\nの3つの受付に、各公演それぞれ1回ずつお申込みいただけます。","id":"auto-aab9c2d03dc15575-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/avemujica-8th/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"应援灯限制","text_zh":"仅允许公告列出的三款Ave Mujica官方手环灯和台北追加公演款；其他荧光棒、应援灯禁止携入和使用。","evidence_ja":"それ以外のサイリウム・ペンライト類の持ち込み・使用は禁止 とさせていただきます。","id":"auto-aab9c2d03dc15575-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/avemujica-8th/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","需迷你专辑「神の名を」首批附券；S/A单日票、一般指定单日票、两日通票分开受理，优先顺序见中文规则。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
