insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-63e890fb109ff84b','official-63e890fb109ff84b','夢限大みゅーたいぷ LIVE TOUR 2027「YMMTric COUNTER POINT」','夢限大みゅーたいぷ 2027 巡演「YMMTric COUNTER POINT」','音乐和声优活动','2027年1月31日至3月26日在福冈、仙台、札幌、大阪、东京、名古屋举办，共7场。三组场次的先行抽选截止日期不同，不能视为一个统一报名窗口。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/06131406/24c07056-66188784-55772d55-5bfdb1c2.jpg","alt":"夢限大みゅーたいぷ 2027 巡演「YMMTric COUNTER POINT」","source_url":"https://bang-dream.com/events/ymmt-tour2027/","checked_on":"2026-10-29"}','[]','[]','[{"title":"申请资格","text_zh":"使用第5张单曲「これはぼくたちの生存のあらすじ」首批生产版附带的申请券。每个序列码可申请1次，各票种最多2张。","evidence_ja":"※ 夢限大みゅーたいぷ 5th Single「これはぼくたちの生存のあらすじ」 初回生産分に封入の申込券でご応募いただけます。\n※シリアルコード1つにつき1回、各券種2枚までお申込みいただけます。","id":"auto-63e890fb109ff84b-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/ymmt-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"福冈与宫城","text_zh":"受理时间为2026年10月11日21:00至11月9日23:59（日本时间）。","evidence_ja":"福岡・宮城公演 最速先行抽選\n受付期間：2026年10月11日(日) 21:00 ～ 11月9日(月) 23:59まで","id":"auto-63e890fb109ff84b-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/ymmt-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"北海道与大阪","text_zh":"受理时间为2026年10月11日21:00至11月23日23:59（日本时间）。","evidence_ja":"北海道・大阪公演 最速先行抽選\n受付期間：2026年10月11日(日) 21:00 ～ 11月23日(月) 23:59まで","id":"auto-63e890fb109ff84b-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/ymmt-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"东京与爱知","text_zh":"受理时间为2026年10月11日21:00至12月14日23:59（日本时间）。","evidence_ja":"東京・愛知公演 最速先行抽選\n受付期間：2026年10月11日(日) 21:00 ～ 12月14日(月) 23:59まで","id":"auto-63e890fb109ff84b-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/ymmt-tour2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","尚未完成各场次参与方式的结构化核实，请阅读中文规则及官方公告。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
