insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-f065242309b768b9','official-f065242309b768b9','千石ユノ主催DJイベント「YUNO’s PARTY Lv.3」','千石ユノ DJ 活动「YUNO’s PARTY Lv.3」','音乐和声优活动','2026年12月5日在东京 duo MUSIC EXCHANGE 举办。昼场12:15入场、13:00开演；夜场17:30入场、18:15开演，均为预计日本时间。门票详情及受理期间尚待公布。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/11/16140507/b14a9de2-809b40d7-3a92cf86-9938c638.jpg","alt":"千石ユノ DJ 活动「YUNO’s PARTY Lv.3」","source_url":"https://bang-dream.com/events/yumemita_yunos_party_lv3/","checked_on":"2026-10-29"}','[]','[]','[{"title":"门票未公布","text_zh":"门票详情和报名受理期间将于之后公布，不能判断报名已开放。","evidence_ja":"※チケットの詳細や受付期間は後日公開いたします。","id":"auto-f065242309b768b9-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_yunos_party_lv3/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","门票详情与受理期间后续公布；昼场13:00、夜场18:15开演（日本时间）。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
