insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-574a22a1d83b735f','official-574a22a1d83b735f','集え！ゆめみた筋トレ部 ～輝け！上腕二頭筋～','集合！夢限大みゅーたいぷ健身部 ～闪耀吧！肱二头肌～','其他联动','2026年11月21日在东京GARDEN 新木場 FACTORY举办昼夜两场，出演者为仲町あられ与藤都子。站立位置指定票5,900日元（含税），一般发售为先到先得。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/08/27161555/785831f3-88ed8c2e-7e6b5011-b95ffaf7.jpg","alt":"集合！夢限大みゅーたいぷ健身部 ～闪耀吧！肱二头肌～","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","checked_on":"2026-10-29"}','[]','[]','[{"title":"一般发售","text_zh":"2026年10月18日12:00起受理，售罄即止，仅电子票，每人最多2张。","evidence_ja":"※先着順・上限数に達し次第終了\n※スマチケのみの受付となります。\n※お一人様につき2枚までお申込みいただけます。","id":"auto-574a22a1d83b735f-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","仅电子票，每人最多2张，昼场13:30、夜场17:30开演（日本时间）。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
