insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-7fb8374c18208450','official-7fb8374c18208450','スタァライト九九組 オーケストラライブ2027','Starlight九九组 管弦乐演唱会2027（详细票务）','音乐和声优活动','2027年1月23日在东京SGCホール有明举行。昼场12:30入场、13:30开演；夜场17:30入场、18:30开演，各约2小时20分钟。含周边票15,500日元、一般席11,000日元，均含税。详情页已经公布了票务，旧新闻中的“待公布”不能代表最新状态。',null,'[]','[]','[{"title":"きゃにめ先行已截止","text_zh":"该轮申请于2026年9月8日至9月29日23:59受理，10月2日19:00后公布结果，支付截止为10月5日23:59；目前这些时间均已过去。","evidence_ja":"【申込受付期間】2026/09/08(火) ～ 2026/09/29(火) 23:59","id":"auto-7fb8374c18208450-rule-0","kind":"参加","source_url":"https://revuestarlight.com/event/11130/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"电子票与数量","text_zh":"每人每场只能选择一种票种，最多2张；须安装免费的「ポニキャン」App，且仅以该App发券。","evidence_ja":"枚数制限： お一人様 各公演 どちらか1券種 2枚まで","id":"auto-7fb8374c18208450-rule-1","kind":"参加","source_url":"https://revuestarlight.com/event/11130/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"儿童限制","text_zh":"学龄前儿童不可入场；申请人数多时采用抽选。","evidence_ja":"※未就学児童入場不可","id":"auto-7fb8374c18208450-rule-2","kind":"参加","source_url":"https://revuestarlight.com/event/11130/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","きゃにめ先行已截止。每人每场一种票种最多2张，须使用ポニキャンApp。后续售票请查看官方。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
