insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-96f2d29dd4fe37bf','official-96f2d29dd4fe37bf','LoveLive! Series 15th Anniversary ラブライブ！フェス','Love Live! 系列15周年 Love Live! Fes','音乐和声优活动','2026年11月14、15日在名古屋Vantelin Dome举办，μ’s、Aqours、虹咲、Liella!、莲之空、人生不易部及音乐剧嘉宾参加。一般第二轮抽选于10月25日23:59（日本时间）截止；活动已公布不代表仍有票可申请。','{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/02/13/1002/MTLGhpBqwB7hnEwW/eHMg6nlsLyB31Vqd.jpeg","alt":"Love Live! 系列15周年 Love Live! Fes","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-29"}','[]','[]','[{"title":"两天时间与地点","text_zh":"11月14日14:30入场、16:30开演；15日13:30入场、15:30开演。场馆为爱知县名古屋Vantelin Dome。","evidence_ja":"日程・会場\n■日程\nDay.1：2026年11月14日（土）14:30開場／16:30開演\nDay.2：2026年11月15日（日）13:30開場／15:30開演\n■会場\n愛知・ バンテリンドーム ナゴヤ","id":"auto-96f2d29dd4fe37bf-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"票价与视线","text_zh":"指定席及注释指定席15,000日元，视线受限席13,000日元，U-20为7,500日元。注释席和视线受限席可能看不清或看不到部分舞台、映像。","evidence_ja":"チケット料金\n全席指定：15,000円（税込）\n注釈付き指定席：15,000円（税込）\n見切れ席：13,000円（税込）\nU-20割引チケット：7,500円（税込）\nアリーナS席アップグレードチケット（グッズ付き）：＋15,000円\nアリーナA席アップグレードチケット（グッズ付き）：＋10,000円\n※注釈付き指定席…ステージや映像の一部が見えづらい、または見えないお席になります。\n※見切れ席…ステージや映像が見えづらい、または見えないお席になります。","id":"auto-96f2d29dd4fe37bf-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"最新轮次已截止","text_zh":"第二轮一般抽选为10月13日18:00至25日23:59；10月30日13:00计划公布结果，仅信用卡付款。每人每场每类最多4张，U-20最多2张，可报多场。均为日本时间。","evidence_ja":"チケット申込\n一般発売（2次抽選）\n■受付URL： https://eplus.jp/ll15th/\n■受付期間：2026年10月13日（火）18:00～10月25日（日）23:59\n■当落発表：2026年10月30日（金）13:00予定\n※枚数制限：お一人様1公演につき、それぞれ4枚までお申込み可能／U-20割引チケットは1公演につき、2枚まで（複数公演申込可能）。\n※本受付では全席指定、注釈付き指定席、見切れ席、U-20割引チケットを販売いたします。\n※クレジットカード決済のみ受付となります。","id":"auto-96f2d29dd4fe37bf-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"U-20限制","text_zh":"演出当天申请者和同行者均须未满20岁，需提供年龄证明；每人每场最多2张，不可升席。","evidence_ja":"U-20割引チケットについて\n本公演は、20歳未満の方にもご参加いただきやすくするため、対象の方に向け「U-20割引チケット」を販売いたします。\n・公演当日時点で20歳未満の方が購入できるチケットとなります。\n・一般発売に合わせ販売予定です。枚数には限りがございますので、あらかじめご了承ください。\n・当日はご入場にあたり、年齢を確認できる身分証明書を確認させていただきます。\n・U-20割引チケットはお一人様1公演につき2枚までお申込みいただけますが、同行者の方も公演当日時点で20歳未満の方に限ります。あらかじめご了承ください。\n・U-20割引チケットはアップグレード対象外となります。","id":"auto-96f2d29dd4fe37bf-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"升席已结束","text_zh":"Arena S另加15,000日元、A另加10,000日元；只面向系列六种先行中选并付款者。第一轮9月13日截止，第二轮9月23日截止，均已结束。升席票不能代替普通入场票。","evidence_ja":"■アップグレード受付（終了）\n【1次抽選】\n受付期間：2026年8月15日（土）12:00～9月13日（日）23:59\n当落発表：2026年9月19日（土）13:00～\n入金期間：2026年9月19日（土）13:00～9月22日（火・祝）21:00\n※支払い方法：クレジットカード・コンビニ／ATM・ネットバンキング（ペイジー）がお選びいただけます。\n【2次抽選】\n受付期間：2026年9月19日（土）12:00～9月23日（水・祝）23:59\n当落発表：2026年10月2日（金）13:00～\n※支払い方法：クレジットカードのみとなります。\n【お申込み条件・対象のお客様】\n全6種のラブライブ！シリーズ先行にて「全席指定：15,000円（税込）」のチケットにご当選され、ご入金が完了のお申込ご本人様。","id":"auto-96f2d29dd4fe37bf-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"赠品领取","text_zh":"升席特典演出当日现场领取，未领取作废，不邮寄。申请者和同行者均需eplus App下载周边兑换券，同行者须事前获分配兑换券。","evidence_ja":"※S席特典とA席特典の「アクリルチャーム付きラミネートパス」は同じアイテムとなります。\n※「アクリルチャーム付きラミネートパス」はDay.1、Day.2でデザインが異なります。\n※グッズは公演当日に会場でのお渡しを予定しております。当日の受け渡しに関する詳細は後日ご案内いたします。\n※公演当日にお受け取りができない場合は無効となります。事前・事後の発送は行いませんので、あらかじめご了承ください。\n※不良品の交換は当日のみ対応いたします。\n※グッズ付きチケットをご購入の方は、別途「グッズ引換券」（スマチケ）のダウンロードが必要となります。「グッズ引換券」のダウンロードにはイープラスアプリ（無料）のインストールが必要です。\n※複数枚お申込みの場合、事前に必ず同行者様へ「グッズ引換券」の分配をおこなってください。「グッズ引換券」を分配していない場合、同行者様はグッズのお受け取りができません。\n※同行者の方もイープラスアプリ（無料）をインストールできるスマートフォンが必要です。（申込者の方と同様の動作機種・推奨環境が必要です）\n※チケットご購入時の手数料に、グッズ引換にかかる手数料も含まれます。","id":"auto-96f2d29dd4fe37bf-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"入场与取消","text_zh":"3岁以上收费、需eplus会员、另收手续费；仅受理期可改退申请，中选后不能取消购买。申请者和同行者须人脸登记，携带照片证件，禁止酒类及酒后入场。","evidence_ja":"※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、先着順ではなく、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。","id":"auto-96f2d29dd4fe37bf-rule-6","kind":"参加","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","最新一般第二轮已截止，仅信用卡付款；10月30日13:00（日本时间）计划公布结果。不能据此推断余票。"]','published','2026-10-29T12:15:33.162Z','2026-10-29T12:15:33.162Z') on conflict do nothing;
